from __future__ import annotations

import argparse
import subprocess
import sys
from pathlib import Path


ROOT = Path(__file__).parent.resolve()


def _run(*args: str) -> int:
    return subprocess.call(args, cwd=ROOT)


def run_tests(with_coverage: bool = False) -> int:
    command = [sys.executable, "-m", "pytest"]
    if with_coverage:
        command.extend(["--cov=justext", "--cov-report=term-missing"])
    return _run(*command)


def list_stoplists() -> int:
    return _run(sys.executable, "-m", "justext", "--list-stoplists")


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Small project task runner.")
    parser.add_argument("task", choices=("test", "coverage", "stoplists"))
    args = parser.parse_args(argv)

    if args.task == "test":
        return run_tests(with_coverage=False)
    if args.task == "coverage":
        return run_tests(with_coverage=True)
    return list_stoplists()


if __name__ == "__main__":
    raise SystemExit(main())

